294	
295	/** Keeps the people's claims on a sheet. A claim with no date is dated the sheet's today. */
296	@Service
297	public class ClaimService {
298	
299	    private final ClaimRepository claims;
300	    private final PersonRepository people;
301	    private final RateService rates;
302	    private final SheetService sheets;
303	    private final Audit audit;
304	
305	    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
306	            Audit audit) {
307	        this.claims = claims;
308	        this.people = people;
309	        this.rates = rates;
310	        this.sheets = sheets;
311	        this.audit = audit;
312	    }
313	
314	    public List<Claim> list(String sheetId) {
315	        return claims.findBySheetIdOrderByIdDesc(sheetId);
316	    }
317	
318	    @Transactional
319	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note) {
320	        Person person = people.findByIdAndSheetId(personId, sheetId)
321	                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
322	        Claim saved = claims.saveAndFlush(new Claim(sheetId, personId, amount, dateOr(sheetId, date), noteOf(note)));
323	        audit.recordOnCommit(record("CLAIM_ADDED", user, person, saved));
324	        return saved;
325	    }
326	
327	    @Transactional
328	    public Claim update(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note) {
329	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
330	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
331	        claim.setAmount(amount);
332	        claim.setDate(dateOr(sheetId, date));
333	        claim.setNote(noteOf(note));
334	        Claim saved = claims.saveAndFlush(claim);
335	        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
336	                .orElseThrow(() -> new PersonNotFoundException(sheetId, saved.getPersonId()));
337	        audit.recordOnCommit(record("CLAIM_EDITED", user, person, saved));
338	        return saved;
339	    }
340	
341	    /** Move a claim to another status, if its current one allows it; refused otherwise. */
342	    @Transactional
343	    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus status) {
344	        Claim claim = claims.findForUpdate(id, sheetId)
345	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
346	        if (!claim.getStatus().canMoveTo(status)) {
347	            throw new ClaimStatusException(id, claim.getStatus(), status);
348	        }
349	        // Four eyes: whoever opened a claim cannot also settle it.
350	        if (status == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
351	            throw new ClaimSettledByOpenerException(id, user);
352	        }
353	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
354	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
355	        claim.setStatus(status);
356	        // Settling fixes the due at the rate the person's grade has on the claim's date; with no rate it stays live.
357	        String due = "";
358	        if (status == ClaimStatus.SETTLED) {
359	            BigDecimal settledDue = rates.rateOn(sheetId, person.getGrade(), claim.getDate())
360	                    .map(Rate::getPct)
361	                    .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN))
362	                    .orElse(null);
363	            claim.setSettledDue(settledDue);
364	            due = " due=" + (settledDue == null ? "n/a" : settledDue.toPlainString());
365	        }
366	        // The CLAIM_VOIDED record carries the number the claim had.
367	        Long number = claim.getNumber();
368	        if (status == ClaimStatus.OPEN) {
369	            number = sheets.nextClaimNumber(sheetId);
370	            claim.setNumber(number);
371	            claim.setOpenedBy(user);
372	        } else if (status == ClaimStatus.VOID) {
373	            claim.setNumber(null);
374	        }
375	        Claim saved = claims.saveAndFlush(claim);
376	        String event = switch (status) {
377	            case OPEN -> "CLAIM_OPENED";
378	            case SETTLED -> "CLAIM_SETTLED";
379	            case VOID -> "CLAIM_VOIDED";
380	            case DRAFT -> throw new IllegalStateException();
381	        };
382	        audit.recordOnCommit(record(event, user, person, saved) + numberOf(number) + due);
383	        return saved;
384	    }
385	
386	    /** The amount as shown (two decimals) and the date as yyyy-mm-dd. */
387	    private static String record(String event, String user, Person person, Claim claim) {
388	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
389	                + " amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
390	                + " date=" + claim.getDate();
391	    }
392	
393	    /** The claim's number at the end of an audit record, or nothing when it has none. */
394	    private static String numberOf(Long number) {
395	        return number == null ? "" : " number=" + number;
396	    }
397	
398	    private LocalDate dateOr(String sheetId, LocalDate date) {
399	        return date != null ? date : sheets.today(sheetId);
400	    }
401	
402	    private static String noteOf(String note) {
403	        return note == null ? "" : note.trim();
404	    }
405	}
