433	
434	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID. */
435	public enum ClaimStatus {
436	    DRAFT, OPEN, SETTLED, VOID;
437	
438	    /** Whether a claim in this status may move to the next one. */
439	    public boolean canMoveTo(ClaimStatus next) {
440	        return switch (next) {
441	            case OPEN -> this == DRAFT;
442	            case SETTLED -> this == OPEN;
443	            case VOID -> this == DRAFT || this == OPEN;
444	            case DRAFT -> false;
445	        };
446	    }
447	
448	    /** Whether a claim in this status counts toward claimed and the totals. */
449	    public boolean counts() {
450	        return this == OPEN || this == SETTLED;
451	    }
452	}
