651	import java.util.List;
652	import net.officefloor.hq.app.Audit;
653	import net.officefloor.hq.app.sheet.SheetNotFoundException;
654	import net.officefloor.hq.app.sheet.SheetRepository;
655	import org.springframework.dao.DataIntegrityViolationException;
656	import org.springframework.orm.ObjectOptimisticLockingFailureException;
657	import org.springframework.stereotype.Service;
658	import org.springframework.transaction.annotation.Transactional;
659	
660	/** Keeps the people on a sheet. */
661	@Service
662	public class PersonService {
663	
664	    private final PersonRepository people;
665	    private final SheetRepository sheets;
666	    private final Audit audit;
667	
668	    public PersonService(PersonRepository people, SheetRepository sheets, Audit audit) {
669	        this.people = people;
670	        this.sheets = sheets;
671	        this.audit = audit;
672	    }
673	
674	    public List<Person> list(String sheetId) {
675	        return people.findBySheetIdOrderByIdAsc(sheetId);
676	    }
677	
678	    @Transactional
679	    public Person add(String sheetId, String user, String name, String grade) {
680	        if (!sheets.existsById(sheetId)) {
681	            throw new SheetNotFoundException(sheetId);
682	        }
683	        if (people.existsBySheetIdAndNameKey(sheetId, Person.key(name))) {
684	            throw new PersonNameTakenException(sheetId, name.trim());
685	        }
686	        Person saved = save(new Person(sheetId, name, grade));
687	        audit.recordOnCommit(record("PERSON_ADDED", user, saved));
688	        return saved;
689	    }
690	
691	    @Transactional
692	    public Person update(String sheetId, String user, Long id, Long version, String name, String grade) {
693	        Person person = people.findByIdAndSheetId(id, sheetId)
694	                .orElseThrow(() -> new PersonNotFoundException(sheetId, id));
695	        if (version != null && version != person.getVersion()) {
696	            throw new PersonVersionConflictException(sheetId, id);
697	        }
698	        if (people.existsBySheetIdAndNameKeyAndIdNot(sheetId, Person.key(name), id)) {
699	            throw new PersonNameTakenException(sheetId, name.trim());
700	        }
701	        person.setName(name);
702	        person.setGrade(grade);
703	        Person saved = save(person);
704	        audit.recordOnCommit(record("PERSON_EDITED", user, saved));
705	        return saved;
706	    }
707	
708	    private static String record(String event, String user, Person person) {
709	        return event + " sheet=" + person.getSheetId() + " by=" + user
710	                + " name=" + person.getName() + " grade=" + person.getGrade();
711	    }
712	
713	    private Person save(Person person) {
714	        try {
715	            return people.saveAndFlush(person);
716	        } catch (DataIntegrityViolationException e) {
717	            // Another user took the name at the same moment: the unique index refused it.
718	            throw new PersonNameTakenException(person.getSheetId(), person.getName());
719	        } catch (ObjectOptimisticLockingFailureException e) {
720	            // Another user saved the person at the same moment.
721	            throw new PersonVersionConflictException(person.getSheetId(), person.getId());
722	        }
723	    }
724	}
