753	/** Keeps the rates for each grade on a sheet, each in force from its from-date. */
754	@Service
755	public class RateService {
756	
757	    private final RateRepository rates;
758	    private final SheetRepository sheets;
759	    private final Audit audit;
760	
761	    public RateService(RateRepository rates, SheetRepository sheets, Audit audit) {
762	        this.rates = rates;
763	        this.sheets = sheets;
764	        this.audit = audit;
765	    }
766	
767	    public List<Rate> list(String sheetId) {
768	        return rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
769	    }
770	
771	    /**
772	     * The grade's rate in force on the date: the one with the latest from-date on or before it, an
773	     * undated rate counting as from the beginning of time. Empty when the date is before every rate.
774	     */
775	    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date) {
776	        return rates.findBySheetIdAndGrade(sheetId, grade).stream()
777	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
778	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())));
779	    }
780	
781	    /** Set the grade's rate from the from-date (null: from the beginning of time), replacing the one it had. */
782	    @Transactional
783	    public Rate set(String sheetId, String user, String grade, LocalDate fromDate, BigDecimal pct) {
784	        if (!sheets.existsById(sheetId)) {
785	            throw new SheetNotFoundException(sheetId);
786	        }
787	        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, fromDate).orElse(null);
788	        if (rate == null) {
789	            rate = new Rate(sheetId, grade, fromDate, pct);
790	        } else {
791	            rate.setPct(pct);
792	        }
793	        Rate saved;
794	        try {
795	            saved = rates.saveAndFlush(rate);
796	        } catch (DataIntegrityViolationException e) {
797	            throw new RateTakenException(sheetId, grade);
798	        }
799	        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + saved.getGrade()
800	                + " rate=" + saved.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
801	                + (saved.getFromDate() == null ? "" : " from=" + saved.getFromDate()));
802	        return saved;
803	    }
804	}
