888	/**
889	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
890	 * so tests can assert side-effects by reading that file — the second test-assertion channel
891	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
892	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
893	 *
894	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
895	 * SYNC) so a test reads the record immediately.
896	 */
897	@Service
898	public class Audit {
899	
900	    private final Path file;
901	
902	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
903	        this.file = Path.of(path);
904	    }
905	
906	    /** Append one audit record. Tests assert the exact line(s) in the file. */
907	    public synchronized void record(String entry) {
908	        try {
909	            Path parent = file.toAbsolutePath().getParent();
910	            if (parent != null) {
911	                Files.createDirectories(parent);
912	            }
913	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
914	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
915	        } catch (IOException e) {
916	            throw new UncheckedIOException(e);
917	        }
918	    }
