920	    /**
921	     * Append one audit record once the current transaction commits, so a change that is refused or
922	     * rolled back writes nothing. Outside a transaction the record is appended at once.
923	     */
924	    public void recordOnCommit(String entry) {
925	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
926	            record(entry);
927	            return;
928	        }
929	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
930	            @Override
931	            public void afterCommit() {
932	                record(entry);
933	            }
934	        });
935	    }
